<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function pupil_profile_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())pupil_profile_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))pupil_profile_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);$role=(string)$_SESSION['role'];if(!in_array($role,['admin','director','sub_director','headteacher'],true))pupil_profile_json(403,['ok'=>false,'message'=>'Only school leadership can edit pupil profiles.']);if($_SERVER['REQUEST_METHOD']!=='POST')pupil_profile_json(405,['ok'=>false,'message'=>'Method not allowed.']);if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))pupil_profile_json(400,['ok'=>false,'message'=>'Your session expired. Refresh and try again.']);
$uid=(int)$_SESSION['user_id'];$school=filter_var($_POST['school_id']??null,FILTER_VALIDATE_INT);$pupil=filter_var($_POST['pupil_id']??null,FILTER_VALIDATE_INT);$first=trim((string)($_POST['first_name']??''));$middle=trim((string)($_POST['middle_name']??''));$last=trim((string)($_POST['last_name']??''));$dob=trim((string)($_POST['date_of_birth']??''));$scholar=(string)($_POST['scholar_type']??'');$guardian=trim((string)($_POST['guardian_name']??''));$phone=trim((string)($_POST['guardian_phone']??''));$validDob=$dob===''||(preg_match('/^\d{4}-\d{2}-\d{2}$/',$dob)&&checkdate((int)substr($dob,5,2),(int)substr($dob,8,2),(int)substr($dob,0,4))&&$dob<=date('Y-m-d'));if(!$school||!$pupil||$first===''||$last===''||mb_strlen($first)>80||mb_strlen($middle)>80||mb_strlen($last)>80||!$validDob||!in_array($scholar,['day','boarding'],true)||mb_strlen($guardian)>140||mb_strlen($phone)>30)pupil_profile_json(422,['ok'=>false,'message'=>'Check required names, date of birth, scholar type, and contact field lengths.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())pupil_profile_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
try{$db->beginTransaction();$q=$db->prepare('SELECT id,first_name,middle_name,last_name,date_of_birth,scholar_type,guardian_name,guardian_phone,status FROM pupils WHERE id=? AND school_id=? FOR UPDATE');$q->execute([$pupil,$school]);$old=$q->fetch();if(!$old)throw new DomainException('Pupil not found in this school.');$changed=[];foreach(['first_name'=>$first,'middle_name'=>$middle?:null,'last_name'=>$last,'date_of_birth'=>$dob?:null,'scholar_type'=>$scholar,'guardian_name'=>$guardian?:null,'guardian_phone'=>$phone?:null] as $key=>$value){$before=$old[$key]===null?null:(string)$old[$key];$after=$value===null?null:(string)$value;if($before!==$after)$changed[]=$key;}if(!$changed)throw new DomainException('No profile changes were entered.');$q=$db->prepare('UPDATE pupils SET first_name=?,middle_name=?,last_name=?,date_of_birth=?,scholar_type=?,guardian_name=?,guardian_phone=? WHERE id=? AND school_id=?');$q->execute([$first,$middle?:null,$last,$dob?:null,$scholar,$guardian?:null,$phone?:null,$pupil,$school]);$displayName=trim($first.' '.($middle?:'').' '.$last);$q=$db->prepare('SELECT user_id FROM pupil_accounts WHERE pupil_id=? AND school_id=? AND active=1');$q->execute([$pupil,$school]);$learnerUser=$q->fetchColumn();if($learnerUser!==false)$db->prepare("UPDATE users SET name=? WHERE id=? AND role='pupil'")->execute([$displayName,(int)$learnerUser]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'update_pupil_profile','pupil',$pupil,json_encode(['school_id'=>$school,'changed_fields'=>$changed,'pupil_status'=>$old['status']],JSON_THROW_ON_ERROR)]);$db->commit();pupil_profile_json(200,['ok'=>true,'message'=>'Pupil profile updated.','data'=>['pupil_id'=>$pupil,'first_name'=>$first,'middle_name'=>$middle,'last_name'=>$last,'display_name'=>$displayName,'date_of_birth'=>$dob,'scholar_type'=>$scholar,'guardian_name'=>$guardian,'guardian_phone'=>$phone,'changed_fields'=>$changed]]);}catch(DomainException $e){if($db->inTransaction())$db->rollBack();pupil_profile_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Pupil profile update failed: '.$e->getMessage());pupil_profile_json(500,['ok'=>false,'message'=>'Pupil profile could not be saved.']);}
